    Q = [[0] * n for _ in range(n)]
    for clause in CNF:
        for lit1 in clause:
            i = abs(lit1) - 1
            for lit2 in clause:
                j = abs(lit2) - 1
                if lit1 > 0 and lit2 > 0:
                    Q[i][j] += 1
    gaussian_elimination(Q)
    rank = sum(1 for row in Q if any(row))
    return rank

def resolution_proofs(CNF):
